function transform (message, context) {
  const contextUser = context.get('__user');
  const testPersonId = context.get('testPersonId');
  const personId = (testPersonId && testPersonId.length > 0)
    ? testPersonId
    : (contextUser && contextUser.id) ? contextUser.id : '';
  context.set('personId', personId);
  return { payload: {} }, context;
}

function transform (message, context) {
  const person = message && message.payload;
  if (!person) {
    return { payload: { success: false, message: 'No person record returned', data: null } };
  }
  const names = Array.isArray(person.names) ? person.names[0] : person.names;
  return {
    payload: {
      success: true,
      data: {
        id: person.id,
        firstName: names && names.firstName,
        lastName: names && names.lastName,
        preferredName: names && names.preferredName,
        roles: person.roles,
        credentials: person.credentials
      }
    }
  };
}
